function setupLiquidNav(){const menu=q('.nav nav');if(!menu||q('.liquid-indicator'))return;const indicator=document.createElement('span');indicator.className='liquid-indicator';menu.prepend(indicator);const move=link=>{const host=menu.getBoundingClientRect(),item=link.getBoundingClientRect();indicator.style.left=(item.left-host.left)+'px';indicator.style.width=item.width+'px';indicator.style.opacity='1'};const active=menu.querySelector('a.active')||menu.querySelector('a');if(active)requestAnimationFrame(()=>move(active));menu.querySelectorAll('a').forEach(link=>link.addEventListener('click',e=>{if(matchMedia('(max-width:1024px)').matches||link.target||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();move(link);menu.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a===link));setTimeout(()=>{location.href=link.href},260)}));addEventListener('resize',()=>{const current=menu.querySelector('a.active');if(current)move(current)},{passive:true})}
