function setupAboutRedesign(){const page=q('.about-page');if(!page)return;page.classList.remove('about-page','page','wrap');page.classList.add('about-redesign');page.innerHTML='<div class="about-top"><div class="about-mark">JIYU<span>Gebit</span></div><div class="about-copy-new"><small>ABOUT</small><h1>\u65e8\u4e8e\u8bb0\u5f55\uff0c\u800c\u975e\u6b62\u4e8e\u8bb0\u5f55</h1><p>\u6211\u662f\u6781\u5c7f Gebit\uff0c\u4e00\u540d\u7528\u5f71\u50cf\u3001\u6587\u5b57\u4e0e\u597d\u5947\u5fc3\u8bb0\u5f55\u65e5\u5e38\u7684\u9ad8\u4e2d\u751f\u521b\u4f5c\u8005\u3002</p></div></div><div class="about-bottom"><div class="about-contact"><span class="about-contact-label">\u8054\u7cfb\u6211\u4eec</span><a href="mailto:gebitqwin@outlook.com">gebitqwin@outlook.com</a></div><div class="about-actions about-links"><a href="videos.html">\u770b\u89c6\u9891 \u2192</a><a href="notes.html">\u8bfb\u7b14\u8bb0 \u2192</a><a href="creative.html">\u521b\u610f\u65e0\u9650 \u2192</a></div></div><div class="about-giant">About</div>'}
function setupAboutLinks(){const links=q('.about-links');if(!links)return;const video=links.querySelector('a[href="videos.html"]'),notes=links.querySelector('a[href="notes.html"]');if(video)video.textContent='\u770b\u89c6\u9891 \u2192';if(notes)notes.textContent='\u8bfb\u7b14\u8bb0 \u2192';if(!links.querySelector('a[href="creative.html"]')){const creative=document.createElement('a');creative.href='creative.html';creative.textContent='\u521b\u610f\u65e0\u9650 \u2192';links.append(creative)}}
