const heroPlayerCss=document.createElement('style');heroPlayerCss.textContent='.hero-play-trigger{position:absolute;z-index:3;top:22px;right:22px;width:48px;height:48px;border:1px solid rgba(255,255,255,.62);border-radius:50%;background:rgba(255,255,255,.18);backdrop-filter:blur(14px);color:#fff;font-size:24px;line-height:1;cursor:pointer;transition:transform .25s,background .25s}.hero-play-trigger:hover{background:#00BCD4;transform:scale(1.08)}#hero-fullscreen{position:fixed;z-index:100;inset:0;display:flex;align-items:center;justify-content:center;padding:32px;background:rgba(4,9,11,.97);opacity:0;visibility:hidden;transition:opacity .3s,visibility .3s}#hero-fullscreen.open{opacity:1;visibility:visible}#hero-fullscreen video{width:100%;height:100%;object-fit:contain;transform:scale(.97);transition:transform .35s}#hero-fullscreen.open video{transform:scale(1)}.hero-player-close{position:absolute;z-index:1;top:24px;right:24px;width:48px;height:48px;border:1px solid rgba(255,255,255,.48);border-radius:50%;background:rgba(15,24,28,.55);backdrop-filter:blur(14px);color:#fff;font-size:29px;line-height:1;cursor:pointer}.hero-player-close:hover{background:#00BCD4;border-color:#00BCD4}@media(max-width:1024px){.hero-play-trigger{top:15px;right:15px;width:43px;height:43px}.hero-player-close{top:15px;right:15px;width:43px;height:43px}#hero-fullscreen{padding:0}}';document.head.append(heroPlayerCss);
const heroControlsCss=document.createElement('style');heroControlsCss.textContent='.hero-controls{position:absolute;z-index:1;left:50%;bottom:28px;transform:translateX(-50%);width:min(780px,calc(100% - 48px));display:grid;grid-template-columns:auto 1fr auto auto;align-items:center;gap:14px;padding:11px 15px;border:1px solid rgba(255,255,255,.2);border-radius:18px;background:rgba(14,24,27,.68);backdrop-filter:blur(18px);color:#fff}.hero-controls button{width:34px;height:34px;border:0;border-radius:50%;background:rgba(255,255,255,.12);color:#fff;font-size:14px;cursor:pointer}.hero-controls button:hover{background:#00BCD4}.hero-progress{width:100%;accent-color:#00BCD4;cursor:pointer}.hero-time{min-width:87px;font:11px LemonMilk,sans-serif;white-space:nowrap;color:#d5e5e7}@media(max-width:1024px){.hero-controls{bottom:18px;width:calc(100% - 28px);gap:9px;padding:9px 11px;border-radius:15px}.hero-time{min-width:76px;font-size:9px}.hero-controls button{width:31px;height:31px}}';document.head.append(heroControlsCss);
const close=d=>{if(!d?.open||d.classList.contains('closing'))return;const shared=d.classList.contains('shared-origin');d.classList.add('closing');setTimeout(()=>{d.close();d.classList.remove('closing','shared-origin');d.style.removeProperty('visibility')},shared?480:380)};
function openDialogFrom(d,source){if(!d)return;d.showModal();if(!source)return;d.style.visibility='hidden';const target=d.getBoundingClientRect(),origin=source.getBoundingClientRect();const scale=Math.max(.12,Math.min(1,Math.min(origin.width/target.width,origin.height/target.height)));d.style.setProperty('--shared-x',(origin.left+origin.width/2-target.left-target.width/2)+'px');d.style.setProperty('--shared-y',(origin.top+origin.height/2-target.top-target.height/2)+'px');d.style.setProperty('--shared-scale',scale);requestAnimationFrame(()=>{d.style.removeProperty('visibility');d.classList.add('shared-origin')})}
function heroPlayer(){let player=q('#hero-fullscreen');if(!player){player=document.createElement('div');player.id='hero-fullscreen';player.innerHTML='<button class="hero-player-close" aria-label="Close">&times;</button><video playsinline><source src="media/imjiyu.mp4" type="video/mp4"></video><div class="hero-controls"><button class="hero-toggle" aria-label="Play">&#9654;</button><input class="hero-progress" type="range" min="0" max="100" value="0" aria-label="Progress"><span class="hero-time">00:00 / 00:00</span><button class="hero-mute" aria-label="Mute">&#9835;</button></div>';document.body.append(player);const video=player.querySelector('video'),toggle=player.querySelector('.hero-toggle'),progress=player.querySelector('.hero-progress'),time=player.querySelector('.hero-time'),mute=player.querySelector('.hero-mute');const format=s=>{s=Math.floor(s||0);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')};const sync=()=>{progress.value=video.duration?video.currentTime/video.duration*100:0;time.textContent=format(video.currentTime)+' / '+format(video.duration);toggle.innerHTML=video.paused?'&#9654;':'&#10074;&#10074;';toggle.setAttribute('aria-label',video.paused?'Play':'Pause');mute.innerHTML=video.muted?'&#10005;':'&#9835;'};const hide=()=>{player.classList.remove('open');video.pause()};toggle.onclick=()=>video.paused?video.play():video.pause();mute.onclick=()=>{video.muted=!video.muted;sync()};progress.oninput=()=>{if(video.duration)video.currentTime=video.duration*progress.value/100};video.addEventListener('timeupdate',sync);video.addEventListener('loadedmetadata',sync);video.addEventListener('play',sync);video.addEventListener('pause',sync);video.addEventListener('ended',sync);player.querySelector('.hero-player-close').onclick=hide;player.addEventListener('click',e=>{if(e.target===player)hide()});addEventListener('keydown',e=>{if(e.key==='Escape'&&player.classList.contains('open'))hide()})}player.classList.add('open');const video=player.querySelector('video');video.currentTime=0;video.play().catch(()=>{})}
const heroFilm=q('.intro-film');if(heroFilm&&!heroFilm.querySelector('.hero-play-trigger')){const trigger=document.createElement('button');trigger.className='hero-play-trigger';trigger.type='button';trigger.setAttribute('aria-label','Play full screen');trigger.innerHTML='&#8599;';trigger.onclick=()=>heroPlayer(heroFilm);heroFilm.append(trigger)}
