const chapterDarkCss=document.createElement('style');chapterDarkCss.textContent='.album-dark .chapter-page{min-height:calc(100vh - 100px);padding:130px 0 100px;background:radial-gradient(circle at 75% 20%,#1f3026 0,transparent 34%)}.album-dark .chapter-story{max-width:1180px;margin:auto;padding:0 26px}.album-dark .chapter-story .back{display:inline-block;margin-bottom:72px;color:#d6ff71;text-decoration:none;font:12px LemonMilk,sans-serif}.album-dark .chapter-story .eyebrow{color:#91a09d}.album-dark .chapter-story h1{font:600 clamp(62px,10vw,150px)/.9 YsSong,serif;letter-spacing:-.09em;margin:18px 0 38px}.album-dark .chapter-story>p:not(.eyebrow){max-width:600px;color:#aeb9b7;font:17px/1.9 "HarmonyOS Sans",Harmony,sans-serif;border-top:1px solid #303838;padding-top:22px}.chapter-gallery{margin-top:82px;display:grid;grid-template-columns:repeat(12,1fr);gap:14px}.chapter-photo{grid-column:span 5;position:relative;margin:0;min-height:340px;overflow:hidden;background:#161b1c;border:1px solid #2b3434}.chapter-photo:nth-child(3n+2){grid-column:span 7;margin-top:105px;min-height:450px}.chapter-photo:nth-child(3n){grid-column:span 7;min-height:460px}.chapter-photo img{width:100%;height:100%;display:block;object-fit:cover;filter:saturate(.82);transition:transform .6s ease,filter .4s ease}.chapter-photo:hover img{transform:scale(1.04);filter:saturate(1.1)}.chapter-photo figcaption{position:absolute;left:16px;bottom:14px;color:#d6ff71;font:10px LemonMilk,sans-serif;letter-spacing:.12em;text-shadow:0 1px 8px #000}.chapter-empty{margin-top:72px;padding:34px;border:1px dashed #3b4646;color:#8e9a98;font:14px "HarmonyOS Sans",Harmony,sans-serif}.chapter-count{margin-top:54px;color:#d6ff71;font:11px LemonMilk,sans-serif;letter-spacing:.12em}@media(max-width:1024px){.album-dark .chapter-page{padding-top:100px}.chapter-gallery{margin-top:56px;display:block}.chapter-photo,.chapter-photo:nth-child(3n+2),.chapter-photo:nth-child(3n){min-height:300px;margin:0 0 14px}.chapter-count{margin-top:40px}}';document.head.append(chapterDarkCss);
function contact(){let d=q('#contact-modal');if(!d){d=document.createElement('dialog');d.id='contact-modal';d.innerHTML='<button class="close">&times;</button><div class="modal-copy"><p class="eyebrow">CONTACT</p><h2>\u8054\u7cfb\u65b9\u5f0f</h2><div class="contact-row"><span>Email</span><a href="mailto:gebitqwin@outlook.com">gebitqwin@outlook.com</a></div><div class="contact-row"><span>QQ</span><b>2019680756</b></div></div>';document.body.append(d);d.querySelector('.close').onclick=()=>close(d);d.onclick=e=>{if(e.target===d)close(d)}}d.showModal()}
function video(v,source){const d=q('#video-modal');if(!v||!d)return;q('#modal-cover').src=v.cover;q('#modal-title').textContent=v.title;q('#modal-date').textContent=v.date;q('#modal-desc').textContent=v.description;q('#link-bili').href=v.bilibili||'https://space.bilibili.com/1039063696';q('#link-douyin').href=v.douyin||'https://www.douyin.com/user/MS4wLjABAAAApKL6iI1zG_kdynY4_yaKOkE_2fWt1ChHsszL0UfHm_hhtuFUKvFZSYCzxdCq1EC-?from_tab_name=main';q('#link-xhs').href=v.xiaohongshu||'#';openDialogFrom(d,source)}
function note(n,source){let d=q('#note-modal');if(!d){d=document.createElement('dialog');d.id='note-modal';d.innerHTML='<button class="close">&times;</button><div class="modal-copy"><p class="eyebrow"></p><h2></h2><p></p><a class="detail-link">\u9605\u89c8\u8be6\u60c5 &rarr;</a></div>';document.body.append(d);d.querySelector('.close').onclick=()=>close(d);d.onclick=e=>{if(e.target===d)close(d)}}d.querySelector('.eyebrow').textContent=n.date;d.querySelector('h2').textContent=n.title;d.querySelector('.modal-copy p:not(.eyebrow)').textContent=n.excerpt;d.querySelector('.detail-link').href='note.html?file='+encodeURIComponent(n.file);openDialogFrom(d,source)}
function render(data){const deck=q('#video-deck'),all=q('#all-videos'),nl=q('#note-list'),an=q('#all-notes');const vc=v=>`<article class="video-card" data-id="${v.id}"><img src="${v.cover}" alt="${v.title}"><div class="card-detail"><h3>${v.title}</h3><p>${v.date||''}</p></div></article>`;const nc=n=>`<a class="note-card" data-file="${n.file}" href="note.html?file=${encodeURIComponent(n.file)}"><time>${n.date}</time><h3>${n.title}</h3><p>${n.excerpt}</p></a>`;if(deck)deck.innerHTML=data.videos.slice(0,5).map(vc).join('');if(all)all.innerHTML=data.videos.map(vc).join('');if(nl)nl.innerHTML=data.notes.map(nc).join('');if(an)an.innerHTML=data.notes.map(nc).join('');document.querySelectorAll('.video-card').forEach(x=>x.onclick=()=>video(data.videos.find(v=>v.id===x.dataset.id),x));document.querySelectorAll('.note-card').forEach(x=>x.onclick=e=>{e.preventDefault();note(data.notes.find(n=>n.file===x.dataset.file),x)})}
function albums(data){const list=q('#album-list');if(list)list.innerHTML=data.albums.map(a=>`<a class="film-card" href="album-chapter.html?chapter=${a.id}"><img src="${a.cover}" alt="${a.title}"><div><p>${a.place} / ${a.date}</p><h2>${a.title}</h2><b>\u8fdb\u5165\u7ae0\u8282 &rarr;</b></div></a>`).join('');const page=q('#album-chapter');if(page){const a=data.albums.find(x=>x.id===new URLSearchParams(location.search).get('chapter'))||data.albums[0];page.innerHTML=`<section class="chapter-hero"><img src="${a.cover}"><div class="chapter-overlay wrap"><a class="back" href="album.html">&larr; \u8fd4\u56de\u5f71\u96c6</a><p>${a.place} / ${a.date}</p><h1>${a.title}</h1><p>${a.description}</p></div></section><section class="wrap chapter-photos">${a.photos.map((p,i)=>`<figure><img src="${p}"><figcaption>FRAME ${i+1}</figcaption></figure>`).join('')}</section>`}const manage=q('#manage-data');if(manage)Promise.all([fetch('data/content.json').then(r=>r.json()),fetch('data/videos-12-20.json').then(r=>r.json())]).then(([b,e])=>manage.innerHTML=`<article class="manage-card"><span>VIDEO</span><b>${b.videos.length+e.videos.length}</b><p>\u89c6\u9891\u6761\u76ee</p><a href="videos.html">\u67e5\u770b\u680f\u76ee &rarr;</a></article><article class="manage-card"><span>NOTES</span><b>${b.notes.length}</b><p>Markdown \u7b14\u8bb0</p><a href="notes.html">\u67e5\u770b\u7b14\u8bb0 &rarr;</a></article><article class="manage-card"><span>ALBUMS</span><b>${data.albums.length}</b><p>\u65c5\u884c\u7ae0\u8282</p><a href="album.html">\u67e5\u770b\u5f71\u96c6 &rarr;</a></article>`)}
function albumLayout(data){const where=a=>[a.country,a.place].filter(Boolean).join(' / ');const table=q('#trip-table'),list=q('#album-list');if(table&&list){table.innerHTML=data.albums.map(a=>`<div class="trip-row" data-trip="${a.id}"><b>${where(a)}</b><span>${a.date}</span></div>`).join('');list.innerHTML=data.albums.map(a=>`<a class="trip-strip ${a.cover?'has-cover':''}" data-trip="${a.id}" href="album-chapter.html?chapter=${a.id}" ${a.cover?`style="background-image:url('${encodeURI(a.cover)}')"`:''}><div><p>${where(a)} / ${a.date}</p><h2>${a.title}</h2><b>\u5c55\u5f00\u80f6\u7247 &rarr;</b></div></a>`).join('');const setActive=id=>{document.querySelectorAll('[data-trip]').forEach(el=>el.classList.toggle('active',el.dataset.trip===id))};const linkTrip=el=>{setActive(el.dataset.trip);const strip=list.querySelector(`.trip-strip[data-trip="${el.dataset.trip}"]`);strip?.scrollIntoView({block:'nearest',behavior:'smooth'})};list.querySelectorAll('.trip-strip').forEach(el=>{el.addEventListener('mouseenter',()=>setActive(el.dataset.trip));el.addEventListener('focus',()=>setActive(el.dataset.trip))});table.querySelectorAll('.trip-row').forEach(el=>{el.addEventListener('mouseenter',()=>linkTrip(el));el.addEventListener('focus',()=>linkTrip(el));el.addEventListener('click',()=>linkTrip(el))});setActive(data.albums[0]?.id)}const chapter=q('#album-chapter');if(chapter){const item=data.albums.find(a=>a.id===new URLSearchParams(location.search).get('chapter'))||data.albums[0];const photos=Array.isArray(item.photos)?item.photos:[],thumbnails=Array.isArray(item.thumbnails)?item.thumbnails:[];const gallery=photos.length?`<div class="chapter-count">${String(photos.length).padStart(2,'0')} FRAMES</div><section class="chapter-gallery">${photos.map((p,i)=>`<figure class="chapter-photo"><img loading="${i>1?'lazy':'eager'}" src="${encodeURI(thumbnails[i]||p)}" data-full="${encodeURI(p)}" alt="${item.title} ${i+1}"><figcaption>FRAME ${String(i+1).padStart(2,'0')}</figcaption></figure>`).join('')}</section>`:'<p class="chapter-empty">\u672c\u7ae0\u8282\u6682\u65e0\u7167\u7247\u3002\u5c06\u56fe\u7247\u653e\u5165 album/'+item.id+'/ \u540e\uff0c\u5728\u5185\u5bb9\u7ba1\u7406\u4e2d\u9009\u62e9 4 \u5373\u53ef\u4e00\u952e\u540c\u6b65\u3002</p>';chapter.innerHTML=`<section class="chapter-story wrap"><a class="back" href="album.html">&larr; \u8fd4\u56de\u5f71\u96c6</a><p class="eyebrow">${where(item)} / ${item.date}</p><h1>${item.title}</h1><p>${item.description}</p>${gallery}</section>`;chapter.querySelectorAll('img[data-full]').forEach(img=>{const full=new Image();full.src=img.dataset.full;full.onload=()=>{img.src=full.src;img.removeAttribute('data-full')}})}}
document.querySelectorAll('.nav nav').forEach(nav=>{if(!nav.querySelector('[href="album.html"]')){const a=document.createElement('a');a.href='album.html';a.textContent='\u5f71\u96c6';nav.insertBefore(a,nav.querySelector('[href="about.html"]'))}});
