function setupLineRuler(){if(q('.line-ruler'))return;const ruler=document.createElement('div');ruler.className='line-ruler';ruler.setAttribute('aria-hidden','true');const count=46;for(let i=0;i<count;i++)ruler.append(document.createElement('span'));document.body.append(ruler);const lines=[...ruler.children];let dragging=false,hovering=false;const pageRatio=()=>{const max=document.documentElement.scrollHeight-innerHeight;return max>0?scrollY/max:0};const draw=(ratio,focus=false)=>{const at=ratio*(count-1);lines.forEach((line,i)=>{const d=Math.abs(i-at),peak=focus?Math.max(0,1-d/4):0;line.style.transform=`scaleX(${1+peak*2.9})`;line.style.opacity=String(focus?.42+peak*.58:.42);line.classList.toggle('active',focus&&d<1.35)})};const point=e=>Math.max(0,Math.min(1,(e.clientY-ruler.getBoundingClientRect().top)/ruler.getBoundingClientRect().height));const move=e=>{const ratio=point(e);draw(ratio,true);if(dragging){const max=document.documentElement.scrollHeight-innerHeight;scrollTo({top:ratio*max,behavior:'auto'})}};ruler.addEventListener('pointerenter',e=>{hovering=true;move(e)});ruler.addEventListener('pointermove',move);ruler.addEventListener('pointerleave',()=>{hovering=false;if(!dragging)draw(pageRatio(),false)});ruler.addEventListener('pointerdown',e=>{dragging=true;ruler.setPointerCapture(e.pointerId);move(e)});ruler.addEventListener('pointerup',e=>{dragging=false;ruler.releasePointerCapture?.(e.pointerId);if(!hovering)draw(pageRatio(),false)});addEventListener('scroll',()=>{if(!dragging&&!hovering)draw(pageRatio(),false)},{passive:true});draw(pageRatio(),false)}
