function setupSearchRuler(){const box=q('.search-box'),out=q('.search-results');if(!box||!out||q('.search-ruler'))return;const ruler=document.createElement('div');ruler.className='search-ruler';const count=30;for(let i=0;i<count;i++)ruler.append(document.createElement('span'));box.append(ruler);const lines=[...ruler.children];let dragging=false,hovering=false;const ratio=()=>{const max=out.scrollHeight-out.clientHeight;return max>0?out.scrollTop/max:0};const draw=(at,focus=false)=>{const index=at*(count-1);lines.forEach((line,i)=>{const d=Math.abs(i-index),peak=focus?Math.max(0,1-d/3.5):0;line.style.transform=`scaleX(${1+peak*2.5})`;line.classList.toggle('active',focus&&d<1.2)})};const point=e=>Math.max(0,Math.min(1,(e.clientY-ruler.getBoundingClientRect().top)/ruler.getBoundingClientRect().height));const move=e=>{const at=point(e);draw(at,true);if(dragging)out.scrollTop=at*(out.scrollHeight-out.clientHeight)};ruler.addEventListener('pointerenter',e=>{hovering=true;move(e)});ruler.addEventListener('pointermove',move);ruler.addEventListener('pointerleave',()=>{hovering=false;if(!dragging)draw(ratio(),false)});ruler.addEventListener('pointerdown',e=>{dragging=true;ruler.setPointerCapture(e.pointerId);move(e)});ruler.addEventListener('pointerup',e=>{dragging=false;ruler.releasePointerCapture?.(e.pointerId);if(!hovering)draw(ratio(),false)});out.addEventListener('scroll',()=>{if(!hovering&&!dragging)draw(ratio(),false)},{passive:true});draw(0,false)}
