function setupMobileBackLogo(){const page=(location.pathname.split('/').pop()||'index.html').toLowerCase();const parents={'album-chapter.html':'album.html','note.html':'notes.html','creative.html':'about.html'};const parent=parents[page];const logo=q('.nav>.logo');if(!parent||!logo)return;logo.style.width=logo.getBoundingClientRect().width+'px';logo.setAttribute('aria-label','Back');requestAnimationFrame(()=>logo.classList.add('mobile-back-logo'));logo.addEventListener('click',e=>{if(!matchMedia('(max-width:1024px)').matches)return;e.preventDefault();location.href=parent})}
