const heroWindowMotionCss=document.createElement('style');heroWindowMotionCss.textContent='#hero-fullscreen{z-index:110;background:rgba(4,10,13,.1)!important;backdrop-filter:blur(0);transition:opacity .48s ease,visibility .48s ease!important}#hero-fullscreen.open{backdrop-filter:blur(16px)}#hero-fullscreen.open.closing{opacity:0;visibility:visible}.hero-video-window{position:relative;width:min(1120px,calc(100% - 48px));aspect-ratio:16/9;overflow:hidden;border:1px solid rgba(255,255,255,.34);border-radius:28px;background:#05090b;box-shadow:0 28px 100px rgba(0,0,0,.45);transform-origin:center center}.hero-video-window video{width:100%!important;height:100%!important;object-fit:cover!important;transform:none!important}.hero-video-window .hero-controls{bottom:22px}.hero-video-window .hero-player-close{top:16px;right:16px}.open .hero-video-window{animation:heroWindowOpen .42s cubic-bezier(.16,1,.3,1) .06s both}.open.closing .hero-video-window{animation:heroWindowClose .42s cubic-bezier(.7,0,.84,0) both}@keyframes heroWindowOpen{from{opacity:0;transform:translate(var(--hero-x),var(--hero-y)) scale(var(--hero-scale));filter:blur(6px)}to{opacity:1;transform:translate(0,0) scale(1);filter:blur(0)}}@keyframes heroWindowClose{from{opacity:1;transform:translate(0,0) scale(1);filter:blur(0)}to{opacity:0;transform:translate(var(--hero-x),var(--hero-y)) scale(var(--hero-scale));filter:blur(6px)}}@media(max-width:1024px){.hero-video-window{width:calc(100% - 28px);border-radius:22px}.hero-video-window .hero-controls{bottom:14px}}';document.head.append(heroWindowMotionCss);
