const albumChapterMotionCss=document.createElement('style');albumChapterMotionCss.textContent='.album-trip-opening .trip-strip{transition:opacity .34s ease,transform .46s cubic-bezier(.16,1,.3,1),filter .34s ease!important}.album-trip-opening .trip-strip:not(.trip-opening){opacity:.14;filter:blur(3px);transform:scale(.985)}.album-trip-opening .trip-strip.trip-opening{position:relative;z-index:4;transform:scale(1.025)!important;filter:brightness(1.12)!important}.album-trip-opening .album-sidebar{opacity:.22;filter:blur(3px);transition:opacity .32s ease,filter .32s ease}.album-chapter-enter .chapter-story{animation:albumChapterEnter .52s cubic-bezier(.16,1,.3,1) both}@keyframes albumChapterEnter{from{opacity:0;transform:translateY(26px) scale(.97);filter:blur(5px)}to{opacity:1;transform:none;filter:blur(0)}}@media(max-width:1024px){.album-trip-opening .trip-strip.trip-opening{transform:scale(1.015)!important}.album-chapter-enter .chapter-story{animation-duration:.44s}}';document.head.append(albumChapterMotionCss);
if(sessionStorage.getItem('jiyuAlbumChapterTransition')==='1'){document.body.classList.add('album-chapter-enter');sessionStorage.removeItem('jiyuAlbumChapterTransition')}document.querySelectorAll('.trip-strip[href*="album-chapter.html"]').forEach(link=>link.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();if(document.body.classList.contains('album-trip-opening'))return;document.body.classList.add('album-trip-opening');link.classList.add('trip-opening');sessionStorage.setItem('jiyuAlbumChapterTransition','1');setTimeout(()=>{location.href=link.href},430)}));
const mediaLoaderCss=document.createElement('style');mediaLoaderCss.textContent='.site-loader{position:fixed;z-index:8;inset:0;display:grid;place-items:center;background:rgba(236,249,250,.72);backdrop-filter:blur(18px) saturate(145%);pointer-events:none;transition:opacity .42s ease,visibility .42s ease}.nav,.mobile-dock{z-index:20!important}.site-loader.done{opacity:0;visibility:hidden}.site-loader-mark{color:#182f35;font:700 clamp(25px,4vw,42px)/1 LemonMilk,sans-serif;letter-spacing:-.075em;animation:loaderFade .42s ease both}.site-loader-mark span{margin-left:.08em;color:#41606b;font-weight:400}.site-loader-icon{display:grid;place-items:center;width:66px;height:66px;border:1px solid rgba(49,104,116,.18);border-radius:50%;background:rgba(255,255,255,.26);box-shadow:inset 0 1px 0 rgba(255,255,255,.7);animation:loaderFade .42s ease both}.site-loader-icon img{width:29px;height:29px;opacity:.9}@keyframes loaderFade{from{opacity:0}to{opacity:1}}@media(max-width:1024px){.site-loader-mark{font-size:27px}}.site-dark:not(.album-dark) .site-loader{background:rgba(12,23,26,.74)}.site-dark:not(.album-dark) .site-loader-mark{color:#edfafa}.site-dark:not(.album-dark) .site-loader-mark span{color:#91b9c0}.site-dark:not(.album-dark) .site-loader-icon,.album-dark .site-loader-icon{border-color:rgba(232,249,250,.18);background:rgba(255,255,255,.08)}.site-dark:not(.album-dark) .site-loader-icon img,.album-dark .site-loader-icon img{filter:brightness(0) invert(1)}.album-dark .site-loader{background:rgba(10,14,15,.78)}.album-dark .site-loader-mark{color:#edf4f2}.album-dark .site-loader-mark span{color:#9ba9a7}';document.head.append(mediaLoaderCss);
function setupMediaLoader(){const page=(location.pathname.split('/').pop()||'index.html').toLowerCase(),homeFirst=page==='index.html',icons={'videos.html':'clapperboard','notes.html':'notebook-pen','album.html':'images'},icon=icons[page],cached=media=>{const src=media.currentSrc||media.src||media.querySelector('source')?.src;if(!src)return false;const entry=performance.getEntriesByName(new URL(src,location.href).href).at(-1);return !!entry&&entry.transferSize===0&&entry.encodedBodySize>0};const pending=[...document.querySelectorAll('main img,main video')].filter(media=>!(media.tagName==='VIDEO'?media.readyState>=2:media.complete)&&!cached(media));if(!pending.length)return;const loader=document.createElement('div');loader.className='site-loader';loader.innerHTML=icon?`<div class="site-loader-icon"><img src="https://cdn.jsdelivr.net/npm/lucide-static@1.26.0/icons/${icon}.svg" alt=""></div>`:'<div class="site-loader-mark">JIYU<span>GEBIT</span></div>';document.body.append(loader);const started=performance.now();let finished=false,forceFinish;const finish=()=>{if(finished)return;finished=true;clearTimeout(forceFinish);const wait=Math.max(0,(homeFirst||icon)?420-(performance.now()-started):160-(performance.now()-started));setTimeout(()=>{loader.classList.add('done');setTimeout(()=>loader.remove(),440)},wait)};forceFinish=setTimeout(finish,3600);let left=pending.length;pending.forEach(media=>{const done=()=>{left--;if(left<=0)finish()};media.addEventListener(media.tagName==='VIDEO'?'loadeddata':'load',done,{once:true});media.addEventListener('error',done,{once:true})})}
setupMediaLoader();
function heroPlayer(source=q('.intro-film')){let player=q('#hero-fullscreen');if(!player){player=document.createElement('div');player.id='hero-fullscreen';player.innerHTML='<section class="hero-video-window"><button class="hero-player-close" aria-label="Close">&times;</button><video playsinline><source src="media/imjiyu.mp4" type="video/mp4"></video><div class="hero-controls"><button class="hero-toggle" aria-label="Play">&#9654;</button><input class="hero-progress" type="range" min="0" max="100" value="0" aria-label="Progress"><span class="hero-time">00:00 / 00:00</span><button class="hero-mute" aria-label="Mute">&#9835;</button></div></section>';document.body.append(player);const video=player.querySelector('video'),toggle=player.querySelector('.hero-toggle'),progress=player.querySelector('.hero-progress'),time=player.querySelector('.hero-time'),mute=player.querySelector('.hero-mute');const format=s=>{s=Math.floor(s||0);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')};const sync=()=>{progress.value=video.duration?video.currentTime/video.duration*100:0;time.textContent=format(video.currentTime)+' / '+format(video.duration);toggle.innerHTML=video.paused?'&#9654;':'&#10074;&#10074;';toggle.setAttribute('aria-label',video.paused?'Play':'Pause');mute.innerHTML=video.muted?'&#10005;':'&#9835;'};const hide=()=>{if(!player.classList.contains('open')||player.classList.contains('closing'))return;player.classList.add('closing');video.pause();setTimeout(()=>player.classList.remove('open','closing'),480)};toggle.onclick=()=>video.paused?video.play():video.pause();mute.onclick=()=>{video.muted=!video.muted;sync()};progress.oninput=()=>{if(video.duration)video.currentTime=video.duration*progress.value/100};video.addEventListener('timeupdate',sync);video.addEventListener('loadedmetadata',sync);video.addEventListener('play',sync);video.addEventListener('pause',sync);video.addEventListener('ended',sync);player.querySelector('.hero-player-close').onclick=hide;player.addEventListener('click',e=>{if(e.target===player)hide()});addEventListener('keydown',e=>{if(e.key==='Escape')hide()})}const card=source instanceof Element?source:q('.intro-film'),windowBox=player.querySelector('.hero-video-window');if(card){const from=card.getBoundingClientRect(),to=windowBox.getBoundingClientRect();const scale=Math.max(.12,Math.min(1,Math.min(from.width/to.width,from.height/to.height)));windowBox.style.setProperty('--hero-x',(from.left+from.width/2-to.left-to.width/2)+'px');windowBox.style.setProperty('--hero-y',(from.top+from.height/2-to.top-to.height/2)+'px');windowBox.style.setProperty('--hero-scale',scale)}player.classList.remove('closing');player.classList.add('open');const video=player.querySelector('video');video.currentTime=0;video.play().catch(()=>{})}
const nf=new URLSearchParams(location.search).get('file');if(nf&&q('#markdown'))fetch(nf).then(r=>r.text()).then(t=>q('#markdown').innerHTML=t.split('\n').map(x=>x.startsWith('# ')?`<h1>${x.slice(2)}</h1>`:x?`<p>${x}</p>`:'').join(''));
Promise.all([fetch('data/content.json').then(r=>r.json()),fetch('data/videos-12-20.json').then(r=>r.json())]).then(([b,e])=>render({...b,videos:[...b.videos,...e.videos].sort((x,y)=>(y.date||'').localeCompare(x.date||''))}));fetch('data/albums.json').then(r=>r.json()).then(albumLayout);
